1: import assert from 'node:assert/strict';
2: import { before, after, read } from './functions.mjs';
3: 
4: function deferred() {
5:   let resolve;
6:   const promise = new Promise((done) => { resolve = done; });
7:   return { promise, resolve };
8: }
9: async function sequential(fn, fail = false) {
10:   let stored = 'old';
11:   const cache = new Map([['key', 'old']]);
12:   const db = {
13:     async read() { return stored; },
14:     async write(key, value) {
15:       if (fail) throw new Error('write');
16:       stored = value;
17:     },
18:   };
19:   let error = null;
20:   await fn(db, cache, 'key', 'new').catch((failure) => { error = failure.message; });
21:   const cachedAfterUpdate = cache.get('key') ?? null;
22:   return { stored, cachedAfterUpdate, nextRead: await read(db, cache, 'key'), error };
23: }
24: async function overlapping(fn, lateSnapshot) {
25:   let stored = 'old';
26:   const cache = new Map();
27:   const readerStarted = deferred();
28:   const releaseReader = deferred();
29:   const writerStarted = deferred();
30:   const releaseWriter = deferred();
31:   const db = {
32:     async read() {
33:       const snapshot = stored;
34:       readerStarted.resolve();
35:       await releaseReader.promise;
36:       return snapshot;
37:     },
38:     async write(key, value) {
39:       writerStarted.resolve();
40:       await releaseWriter.promise;
41:       stored = value;
42:     },
43:   };
44:   let pendingRead;
45:   let update;
46:   if (lateSnapshot) {
47:     pendingRead = read(db, cache, 'key');
48:     await readerStarted.promise;
49:     update = fn(db, cache, 'key', 'new');
50:     await writerStarted.promise;
51:     releaseWriter.resolve();
52:     await update;
53:     releaseReader.resolve();
54:   } else {
55:     update = fn(db, cache, 'key', 'new');
56:     await writerStarted.promise;
57:     pendingRead = read(db, cache, 'key');
58:     await readerStarted.promise;
59:     releaseReader.resolve();
60:     await pendingRead;
61:     releaseWriter.resolve();
62:     await update;
63:   }
64:   const overlappingRead = await pendingRead;
65:   return { stored, overlappingRead, cached: cache.get('key') ?? null, nextRead: await read(db, cache, 'key') };
66: }
67: const results = {};
68: for (const [name, fn] of Object.entries({ before, after })) {
69:   results[name] = {
70:     sequential: await sequential(fn),
71:     failedWrite: await sequential(fn, true),
72:     fillDuringWrite: await overlapping(fn, false),
73:     lateSnapshot: await overlapping(fn, true),
74:   };
75: }
76: assert.equal(results.before.fillDuringWrite.nextRead, 'old');
77: assert.equal(results.after.fillDuringWrite.nextRead, 'new', 'post-write deletion removes a cache fill that completed during the write');
78: assert.equal(results.after.fillDuringWrite.overlappingRead, 'old');
79: assert.equal(results.after.failedWrite.cachedAfterUpdate, 'old');
80: assert.equal(results.before.failedWrite.cachedAfterUpdate, null);
81: for (const result of Object.values(results)) {
82:   assert.equal(result.sequential.nextRead, 'new');
83:   assert.equal(result.failedWrite.stored, 'old');
84:   assert.equal(result.failedWrite.error, 'write');
85:   assert.equal(result.lateSnapshot.stored, 'new');
86:   assert.equal(result.lateSnapshot.cached, 'old', 'an older snapshot can refill the cache after invalidation');
87:   assert.equal(result.lateSnapshot.nextRead, 'old');
88: }
89: console.log(JSON.stringify({ assumptions: 'Explicit promise gates schedule snapshot capture, write commit, and cache fill. One process and one Map; no wall-clock timing.', results }, null, 2));

